{
  "passageId": "plastic-polymerization",
  "itemKey": "b",
  "form": "BOGI",
  "situation": {
    "description": "같은 종류의 플라스틱으로 만든 전시품 보호판 두 시제품의 결정 영역 비율을 바탕으로 물성을 비교한다.",
    "slotRef": null,
    "bogiText": "한 연구팀은 같은 종류의 플라스틱으로 전시품 보호판 시제품 A와 B를 만들었다. 플라스틱 전체에서 결정 영역이 차지하는 비율은 A가 25%, B가 55%였다. 두 시제품은 결정 영역 비율 이외에 물성에 영향을 미치는 조건이 모두 같으며, 동일한 조건에서 물성을 비교한다."
  },
  "usedRuleIds": [
    "R4"
  ],
  "steps": [
    {
      "n": 1,
      "given": "결정 영역 비율은 A가 25%, B가 55%이므로 B가 A보다 30%포인트 높다. 다른 조건은 같다.",
      "ruleId": "R4",
      "ruleQuote": "결정 영역이 많아질수록 플라스틱은 유연성이 낮아 충격에 약하고 가공성이 떨어지며 점점 불투명해지지만, 밀도가 높아져 단단해지고 화학 물질에 대한 민감성이 감소하며 열에 의해 잘 변형되지 않는다.",
      "result": "B는 A보다 밀도가 높고 단단하다."
    },
    {
      "n": 2,
      "given": "결정 영역 비율이 B는 55%, A는 25%이고, 다른 조건은 같다.",
      "ruleId": "R4",
      "ruleQuote": "결정 영역이 많아질수록 플라스틱은 유연성이 낮아 충격에 약하고 가공성이 떨어지며 점점 불투명해지지만, 밀도가 높아져 단단해지고 화학 물질에 대한 민감성이 감소하며 열에 의해 잘 변형되지 않는다.",
      "result": "B는 A보다 유연성이 낮고 충격에 약하다."
    },
    {
      "n": 3,
      "given": "결정 영역 비율이 B는 55%, A는 25%이고, 다른 조건은 같다.",
      "ruleId": "R4",
      "ruleQuote": "결정 영역이 많아질수록 플라스틱은 유연성이 낮아 충격에 약하고 가공성이 떨어지며 점점 불투명해지지만, 밀도가 높아져 단단해지고 화학 물질에 대한 민감성이 감소하며 열에 의해 잘 변형되지 않는다.",
      "result": "B는 A보다 가공성이 떨어지고 불투명하다."
    },
    {
      "n": 4,
      "given": "결정 영역 비율이 B는 55%, A는 25%이고, 다른 조건은 같다.",
      "ruleId": "R4",
      "ruleQuote": "결정 영역이 많아질수록 플라스틱은 유연성이 낮아 충격에 약하고 가공성이 떨어지며 점점 불투명해지지만, 밀도가 높아져 단단해지고 화학 물질에 대한 민감성이 감소하며 열에 의해 잘 변형되지 않는다.",
      "result": "B는 A보다 화학 물질에 대한 민감성이 낮고 열에 의해 잘 변형되지 않는다."
    }
  ],
  "derivedFacts": [
    {
      "id": "F1",
      "text": "결정 영역 비율이 55%인 B는 25%인 A보다 밀도가 높고 단단하다.",
      "fromSteps": [
        1
      ],
      "ifDifferent": "다른 조건은 그대로이고 B의 결정 영역 비율이 15%였다면, B는 A보다 밀도가 낮고 덜 단단했을 것이다."
    },
    {
      "id": "F2",
      "text": "두 시제품 중 더 단단한 B가 오히려 유연성은 낮고 충격에는 약하다.",
      "fromSteps": [
        1,
        2
      ],
      "ifDifferent": "다른 조건은 그대로이고 A의 결정 영역 비율이 65%였다면, A가 B보다 단단하면서 유연성이 낮고 충격에 약했을 것이다."
    },
    {
      "id": "F3",
      "text": "A는 B보다 가공성이 좋고 투명하다.",
      "fromSteps": [
        3
      ],
      "ifDifferent": "다른 조건은 그대로이고 A의 결정 영역 비율이 65%였다면, A는 B보다 가공성이 떨어지고 불투명했을 것이다."
    },
    {
      "id": "F4",
      "text": "A보다 충격에 약한 B가 화학 물질에는 덜 민감하고 열에 의해서도 잘 변형되지 않는다.",
      "fromSteps": [
        2,
        4
      ],
      "ifDifferent": "다른 조건은 그대로이고 B의 결정 영역 비율이 15%였다면, B는 A보다 충격에 강하지만 화학 물질에 더 민감하고 열에 의해 더 쉽게 변형되었을 것이다."
    }
  ],
  "selfCheck": "B의 결정 영역 비율이 A보다 높다는 조건을 R4에 대입하여 각 물성의 상대적 차이를 도출했다. 비율 차이로 물성 변화의 크기까지 계산하거나 절대적인 성능을 단정하지 않았으며, 모든 결론과 반사실적 비교의 방향이 규칙과 일치함을 확인했다."
}

